import java.io.BufferedReader;
import java.io.InputStreamReader;

public class bubblestrike {
    public static void main(String[] args) throws Exception {
        BufferedReader reader = new BufferedReader(new InputStreamReader(System.in));
        String[] input = reader.readLine().split(" ");
        int initialX = Integer.parseInt(input[0]);
        double targetProb = Double.parseDouble(input[1]);
        int currentPosition = initialX;
        for (int step = initialX; step > 0; step /= 2) {
            while (currentPosition - step >= 0 && check(currentPosition - step, initialX - (currentPosition - step), targetProb)) {
                currentPosition -= step;
            }
        }
        System.out.println(currentPosition);
        reader.close();
    }

    public static boolean check(int good, int bad, double p) {
        double g = good;
        double b = bad;
        double numerator = (0.25 * b * Math.max(0, b - 1) * g
                + (g * (Math.max(0, g - 1) * Math.max(0, g - 2) / 6.0) + b * 0.5 * g * Math.max(0, g - 1)));
        double denominator = (g + b) * Math.max(0, g + b - 1) * Math.max(0, g + b - 2) / 6.0;
        double result = numerator / denominator;
        return result >= p;
    }
}
